// Merge city config with weather data and evaluate thresholds
const cityConfig = $('City Config').item.json;
const weather = $input.item.json;

const daily = weather.daily;
const hourly = weather.hourly;

// Aggregate next 48h
const next48h = {
  max_temp: Math.max(...daily.temperature_2m_max.slice(0, 2)),
  min_temp: Math.min(...daily.temperature_2m_min.slice(0, 2)),
  total_rain_mm: daily.precipitation_sum.slice(0, 2).reduce((a, b) => a + b, 0),
  total_snow_cm: daily.snowfall_sum.slice(0, 2).reduce((a, b) => a + b, 0),
  max_wind_kmh: Math.max(...daily.windspeed_10m_max.slice(0, 2)),
  min_visibility_m: Math.min(...hourly.visibility.slice(0, 48).filter(v => v != null)),
  max_humidity: Math.max(...hourly.relativehumidity_2m.slice(0, 48).filter(h => h != null))
};

const t = cityConfig.thresholds;
const triggers = [];
let highestSeverity = null;

// Evaluate each condition
const checks = [
  { condition: 'heavy_snow', value: next48h.total_snow_cm, urgent: t.snowfall_cm_urgent, heads_up: t.snowfall_cm_heads_up, label: 'Snowfall', unit: 'cm' },
  { condition: 'heavy_rain', value: next48h.total_rain_mm, urgent: t.rain_mm_urgent, heads_up: t.rain_mm_heads_up, label: 'Rainfall', unit: 'mm' },
  { condition: 'strong_wind', value: next48h.max_wind_kmh, urgent: t.wind_kmh_urgent, heads_up: t.wind_kmh_heads_up, label: 'Wind', unit: 'km/h' },
  { condition: 'extreme_heat', value: next48h.max_temp, urgent: t.temp_max_urgent, heads_up: t.temp_max_heads_up, label: 'Max Temp', unit: '°C' },
  { condition: 'extreme_cold', value: next48h.min_temp, urgent_below: t.temp_min_urgent, heads_up_below: t.temp_min_heads_up, label: 'Min Temp', unit: '°C', invert: true },
  { condition: 'low_visibility', value: next48h.min_visibility_m, urgent_below: t.visibility_m_urgent, heads_up_below: t.visibility_m_heads_up, label: 'Visibility', unit: 'm', invert: true },
  { condition: 'high_humidity', value: next48h.max_humidity, urgent: t.humidity_pct_urgent, heads_up: t.humidity_pct_heads_up, label: 'Humidity', unit: '%' }
];

for (const check of checks) {
  if (check.value == null) continue;

  let severity = null;
  if (check.invert) {
    if (check.urgent_below != null && check.value <= check.urgent_below) severity = 'urgent';
    else if (check.heads_up_below != null && check.value <= check.heads_up_below) severity = 'heads_up';
  } else {
    if (check.urgent != null && check.value >= check.urgent) severity = 'urgent';
    else if (check.heads_up != null && check.value >= check.heads_up) severity = 'heads_up';
  }

  if (severity) {
    triggers.push({ ...check, severity });
    if (severity === 'urgent' || highestSeverity === null) highestSeverity = severity;
  }
}

return [{
  json: {
    city: cityConfig.name,
    country: cityConfig.country,
    should_alert: triggers.length > 0,
    severity: highestSeverity,
    triggers,
    weather_summary: next48h,
    evaluated_at: new Date().toISOString()
  }
}];

// Deduplication: create a fingerprint for this alert
// Alerts with the same fingerprint won't fire again within 6 hours
const data = $input.item.json;

const conditionTypes = data.triggers.map(t => t.condition).sort().join('_');
const fingerprint = `${data.city}_${conditionTypes}_${new Date().toISOString().slice(0, 13)}`;
// Slice to hour (YYYY-MM-DDTHH) → same alert won't repeat within the same hour window
// For 6h dedup, round to nearest 6h block:
const hour = new Date().getUTCHours();
const block = Math.floor(hour / 6) * 6;
const dedupKey = `${data.city}_${conditionTypes}_${new Date().toISOString().slice(0, 10)}_block${block}`;

return [{ json: { ...data, dedup_key: dedupKey, fingerprint } }];

// Use n8n's static workflow data as a lightweight dedup store
// (Works without Redis – suitable for free-tier self-hosted n8n)
const data = $input.item.json;
const key = data.dedup_key;

const store = $getWorkflowStaticData('global');
const now = Date.now();
const SIX_HOURS = 6 * 60 * 60 * 1000;

// Clean up expired keys
for (const k of Object.keys(store)) {
  if (now - store[k] > SIX_HOURS) delete store[k];
}

const alreadySent = !!store[key];

if (!alreadySent) {
  store[key] = now; // Mark as sent
}

return [{ json: { ...data, already_sent: alreadySent } }];

// Build the prompt for Claude
const d = $input.item.json;
const triggerDescriptions = d.triggers.map(t => 
  `- ${t.label}: ${t.value?.toFixed(1)} ${t.unit} (threshold: ${t.invert ? 'below' : 'above'} ${t.severity === 'urgent' ? (t.urgent_below ?? t.urgent) : (t.heads_up_below ?? t.heads_up)} ${t.unit}) → ${t.severity.toUpperCase()}`
).join('\n');

const prompt = `You are an operational intelligence assistant for a field operations platform.

A weather monitoring system has detected conditions that may affect courier operations in ${d.city}, ${d.country} in the next 24–48 hours.

Overall severity: ${d.severity === 'urgent' ? '🚨 URGENT' : '⚠️ HEADS-UP'}

Triggered conditions:
${triggerDescriptions}

Weather summary (next 48h):
- Max temperature: ${d.weather_summary.max_temp}°C
- Min temperature: ${d.weather_summary.min_temp}°C
- Total rainfall: ${d.weather_summary.total_rain_mm.toFixed(1)}mm
- Total snowfall: ${d.weather_summary.total_snow_cm.toFixed(1)}cm
- Max wind speed: ${d.weather_summary.max_wind_kmh.toFixed(0)}km/h

Write a Slack alert for the Local Operations Manager in ${d.city}. Requirements:
1. Start with the severity emoji and city name on the first line
2. In 2–3 sentences, explain what's coming and WHY it matters for courier operations specifically (acceptance rates, delivery times, courier supply, safety)
3. Give 2–3 concrete, actionable steps the OM should take NOW
4. End with a single "Key metric to watch" line
5. Write in plain English. No weather jargon. Max 120 words total.
6. Tone: direct and calm. This is a professional operational alert, not a news broadcast.

Respond with ONLY the Slack message text. No preamble, no explanation.`;

return [{ json: { ...d, llm_prompt: prompt } }];

// Extract Claude's response and merge with alert data
const claudeResponse = $input.item.json;
const previousData = $('Build LLM Prompt').item.json;

const alertText = claudeResponse.content?.[0]?.text ?? 'Alert generation failed – check weather data manually.';

return [{
  json: {
    ...previousData,
    alert_text: alertText
  }
}];
